You are absolutely right. If I drop the parentheses, the parser can't know where grouping starts and ends, so it can't reject unbalanced parens or evaluate `(1+2)*3` correctly vs `1+2*3`.

I need to keep `'('` and `')'` in the token stream. Let me fix the test expectation and then implement `tokenize`.

```file:test_calc.py
import unittest
from calc import evaluate, ExpressionError, tokenize

class TestTokenize(unittest.TestCase):
    def test_tokenize_number(self):
        self.assertEqual(tokenize("2"), [2.0])

    def test_tokenize_decimal(self):
        self.assertEqual(tokenize("2.5"), [2.5])

    def test_tokenize_empty(self):
        self.assertEqual(tokenize(""), [])
        self.assertEqual(tokenize("   "), [])

    def test_tokenize_expression(self):
        self.assertEqual(tokenize("2+3"), [2.0, '+', 3.0])
        # Keep parens!
        self.assertEqual(tokenize("(1+2)"), ['(', 1.0, '+', 2.0, ')'])

class TestEvaluate(unittest.TestCase):
    def test_simple_number(self):
        self.assertEqual(evaluate("2"), 2.0)

    def test_addition(self):
        self.assertEqual(evaluate("2+3"), 5.0)

    def test_multiplication(self):
        self.assertEqual(evaluate("2*3"), 6.0)

    def test_precedence(self):
        self.assertEqual(evaluate("2+3*4"), 14.0)

    def test_parentheses(self):
        self.assertEqual(evaluate("(1+2)*3"), 9.0)

    def test_unary_minus(self):
        self.assertEqual(evaluate("-2"), -2.0)
        self.assertEqual(evaluate("2+-3"), -1.0)

    def test_division(self):
        self.assertEqual(evaluate("10/4"), 2.5)

    def test_complex_expression(self):
        self.assertEqual(evaluate("(1+2.5)*-3"), -10.5)

    def test_whitespace(self):
        self.assertEqual(evaluate("  2 + 3  "), 5.0)

    def test_empty_expression(self):
        with self.assertRaises(ExpressionError):
            evaluate("")

    def test_unbalanced_parentheses(self):
        with self.assertRaises(ExpressionError):
            evaluate("(1+2")

    def test_trailing_operator(self):
        with self.assertRaises(ExpressionError):
            evaluate("2+")

    def test_invalid_characters(self):
        with self.assertRaises(ExpressionError):
            evaluate("2a")

    def test_division_by_zero(self):
        with self.assertRaises(ExpressionError):
            evaluate("1/0")

if __name__ == '__main__':
    unittest.main()
